#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,      // [B, C_in, H_in, W_in]
    const float* weight,     // [out_channels, kernel_size, kernel_size, dilation] (flattened)
    float* output,           // [B, out_channels, H_out, W_out]
    int batch,
    int in_ch,
    int out_ch,
    int stride,
    int pad_h,
    int pad_w,
    int dil,
    int ksize,
    int h_in,
    int w_in) 
{
    // Output height and width
    int H_out = (h_in + 2 * pad_h) * stride - 1;
    int W_out = (w_in + 2 * pad_w) * stride - 1;

    long total_output_elements = batch * out_ch * H_out * W_out;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_output_elements) {
        int b = idx / (out_ch * H_out * W_out);
        int rem = idx % (out_ch * H_out * W_out);
        int c_out = rem / (H_out * W_out);
        rem = rem % (H_out * W_out);
        int h_out = rem / W_out;
        int w_out = rem % W_out;

        float val = 0.0f;

        for (int ci = 0; ci < in_ch; ++ci) {
            // Window start positions with dilation and padding
            int h_start = pad_h + dil * (h_in - ksize / 2);
            int w_start = pad_w + dil * (w_in - ksize / 2);

            for (int kh = 0; kh < ksize; ++kh) {
                for (int kw = 0; kw < ksize; ++kw) {
                    if (h_start + kh >= 0 && h_start + kh < h_in &&
                        w_start + kw >= 0 && w_start + kw < w_in) {
                        long in_idx = ((b * in_ch + ci) * h_in * w_in +
                                      (h_start + kh) * w_in + (w_start + kw));
                        val += input[in_idx] *
                                    weight[out_ch * ksize * ksize * dil +
                                               ci * ksize * ksize * dil +
                                               kh * ksize * dil + kw * ksize * dil];
                    }
                }
            }

            output[idx] = val;
        }
    }
}
"""

